//! Constraint handle implementation.
//!
//! This module provides the ConstraintHandle type for uniquely identifying
//! constraints in the physics world.

use std::fmt;
use std::hash::Hash;

/// A handle to a constraint in the physics world.
///
/// Constraint handles are used to uniquely identify and reference
/// constraints. They are generated by the world when constraints are created.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[cfg_attr(
    feature = "serialization",
    derive(serde::Serialize, serde::Deserialize)
)]
pub struct ConstraintHandle {
    /// Generation counter
    pub generation: u32,
    /// Index within the generation
    pub index: u32,
}

impl ConstraintHandle {
    /// Create a new constraint handle
    #[inline]
    #[must_use]
    pub const fn new(generation: u32, index: u32) -> Self {
        Self { generation, index }
    }

    /// Create a null handle (invalid)
    #[inline]
    #[must_use]
    pub const fn null() -> Self {
        Self {
            generation: 0,
            index: u32::MAX,
        }
    }

    /// Check if the handle is null
    #[inline]
    #[must_use]
    pub fn is_null(&self) -> bool {
        self.index == u32::MAX
    }
}

impl Default for ConstraintHandle {
    fn default() -> Self {
        Self::null()
    }
}

impl fmt::Display for ConstraintHandle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.is_null() {
            write!(f, "ConstraintHandle(null)")
        } else {
            write!(f, "ConstraintHandle({}, {})", self.generation, self.index)
        }
    }
}

/// Generator for constraint handles
#[derive(Debug, Clone)]
pub struct ConstraintHandleGenerator {
    /// Current generation counter
    current_generation: u32,
    /// Current index counter
    current_index: u32,
}

impl ConstraintHandleGenerator {
    /// Create a new handle generator
    #[inline]
    #[must_use]
    pub const fn new() -> Self {
        Self {
            current_generation: 1,
            current_index: 0,
        }
    }

    /// Generate a new handle
    #[inline]
    #[must_use]
    pub fn generate(&mut self) -> ConstraintHandle {
        let handle = ConstraintHandle::new(self.current_generation, self.current_index);
        self.current_index += 1;
        handle
    }

    /// Reset the generator
    #[inline]
    pub fn reset(&mut self) {
        self.current_generation = 1;
        self.current_index = 0;
    }
}

impl Default for ConstraintHandleGenerator {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::hash::Hasher;

    #[test]
    fn test_construction() {
        let handle = ConstraintHandle::new(1, 0);
        assert_eq!(handle.generation, 1);
        assert_eq!(handle.index, 0);
    }

    #[test]
    fn test_null() {
        let null = ConstraintHandle::null();
        assert!(null.is_null());
        assert_eq!(null.index, u32::MAX);
    }

    #[test]
    fn test_default() {
        let default = ConstraintHandle::default();
        assert!(default.is_null());
    }

    #[test]
    fn test_display() {
        let handle = ConstraintHandle::new(1, 5);
        let handle_str = format!("{}", handle);
        assert!(handle_str.contains("ConstraintHandle"));

        let null_str = format!("{}", ConstraintHandle::null());
        assert!(null_str.contains("null"));
    }

    #[test]
    fn test_generator() {
        let mut generator = ConstraintHandleGenerator::new();

        let handle1 = generator.generate();
        assert_eq!(handle1.generation, 1);
        assert_eq!(handle1.index, 0);

        let handle2 = generator.generate();
        assert_eq!(handle2.generation, 1);
        assert_eq!(handle2.index, 1);

        let handle3 = generator.generate();
        assert_eq!(handle3.generation, 1);
        assert_eq!(handle3.index, 2);
    }

    #[test]
    fn test_generator_reset() {
        let mut generator = ConstraintHandleGenerator::new();

        let _ = generator.generate();
        let _ = generator.generate();
        generator.reset();

        let handle = generator.generate();
        assert_eq!(handle.generation, 1);
        assert_eq!(handle.index, 0);
    }

    #[test]
    fn test_hash() {
        let handle1 = ConstraintHandle::new(1, 0);
        let handle2 = ConstraintHandle::new(1, 0);
        let handle3 = ConstraintHandle::new(2, 0);

        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        handle1.hash(&mut hasher);
        let hash1 = hasher.finish();

        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        handle2.hash(&mut hasher);
        let hash2 = hasher.finish();

        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        handle3.hash(&mut hasher);
        let hash3 = hasher.finish();

        assert_eq!(hash1, hash2);
        assert_ne!(hash1, hash3);
    }
}
